from typing import List, Optional, Dict, Any, Literal
from datetime import datetime, timezone
from pydantic import BaseModel, Field


class QuestionItem(BaseModel):
    """Represents a single interview question generated by AI."""
    question_id: str = Field(..., description="Unique identifier for the question")
    question_index: int = Field(..., description="1-based index in the session (e.g., 1 of 6)")
    question_text: str = Field(..., description="The interview question text")
    question_category: str = Field(
        ...,
        description="Category: 'technical', 'behavioral', 'project_deep_dive', or 'system_design'"
    )
    difficulty: Literal["easy", "medium", "hard"] = Field(
        "medium",
        description="Difficulty level of the question"
    )
    context_note: Optional[str] = Field(
        None,
        description="Why this question was chosen (e.g. 'Probing FastAPI experience from resume')"
    )
    sample_answer_hint: Optional[str] = Field(
        None,
        description="Short hint or key topics expected in an ideal answer"
    )


class AnswerScores(BaseModel):
    """5-parameter evaluation rubric scored from 1 to 10."""
    relevance: int = Field(..., ge=1, le=10, description="Did the candidate directly answer the question? (1-10)")
    technical_accuracy: int = Field(..., ge=1, le=10, description="Correctness of technical concepts/syntax (1-10)")
    clarity: int = Field(..., ge=1, le=10, description="Structure, conciseness, and articulation (1-10)")
    depth: int = Field(..., ge=1, le=10, description="Nuance, trade-offs, and edge cases handled (1-10)")
    confidence: int = Field(..., ge=1, le=10, description="Conviction and professional tone (1-10)")


class AnswerEvaluation(BaseModel):
    """Detailed evaluation returned for a candidate's answer."""
    scores: AnswerScores
    average_score: float = Field(..., description="Weighted/arithmetic average score out of 10")
    feedback: str = Field(..., description="Concise, constructive feedback on the response")
    strengths: List[str] = Field(default_factory=list, description="Key strong points observed")
    areas_for_improvement: List[str] = Field(default_factory=list, description="Specific gaps or missing elements")
    ideal_answer_summary: str = Field(..., description="What a top-percentile answer would have included")


class TurnHistoryItem(BaseModel):
    """Record of a completed question-answer turn."""
    question_index: int
    question: QuestionItem
    answer_text: str
    duration_seconds: Optional[int] = 0
    evaluation: AnswerEvaluation
    timestamp: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))


class CombinedTurnResponse(BaseModel):
    """Structured response model generated by Gemini combining evaluation and next question."""
    evaluation: AnswerEvaluation
    next_question: Optional[QuestionItem] = Field(
        None,
        description="Next question if interview has more turns, or null if complete"
    )
    interview_verdict: Optional[str] = Field(
        None,
        description="Short summary if this was the final question"
    )


class StartInterviewRequest(BaseModel):
    """Payload to initiate a new interview session."""
    target_role: str = Field("Full Stack Developer", description="Target job position")
    job_description: Optional[str] = Field(None, description="Optional target job description")
    resume_id: Optional[str] = Field(None, description="Optional MongoDB ID of parsed resume")
    resume_text: Optional[str] = Field(None, description="Optional raw text of resume if no resume_id")
    total_questions: int = Field(6, ge=3, le=10, description="Number of questions in mock session (3-10)")
    initial_difficulty: Literal["easy", "medium", "hard"] = Field("medium")


class StartInterviewResponse(BaseModel):
    """Response returned upon successfully initializing an interview session."""
    session_id: str
    target_role: str
    total_questions: int
    current_question_index: int
    current_difficulty: str
    first_question: QuestionItem
    status: str = "in_progress"


class SubmitAnswerRequest(BaseModel):
    """Payload sent by candidate when submitting an answer."""
    answer_text: str = Field(..., min_length=2, description="Candidate's answer text")
    duration_seconds: Optional[int] = Field(0, description="Seconds spent answering")


class SubmitAnswerResponse(BaseModel):
    """Response after evaluating answer and generating next question."""
    session_id: str
    question_index: int
    evaluation: AnswerEvaluation
    next_question: Optional[QuestionItem] = None
    is_complete: bool = False
    current_difficulty: str
    average_score_so_far: float


class SessionSummary(BaseModel):
    """Final wrap-up summary of the completed interview session."""
    session_id: str
    user_id: str
    target_role: str
    total_questions: int
    completed_turns: int
    overall_average_score: float
    difficulty_progression: List[str]
    category_scores: Dict[str, float]
    status: str
    started_at: datetime
    completed_at: Optional[datetime] = None
